-- Every RemoteEvent in the game is declared here. Add names to the list.
local RunService = game:GetService("RunService")

local EVENT_NAMES = {
	"ShopUpdate", -- server -> client: current offers / shop open state
	"ShopSync", -- client -> server: request the current ShopUpdate
	"BuyOffer", -- client -> server: offer slot index
	"RerollOffers", -- client -> server
	"CombatFx", -- server -> client: (kind "Hit" | "Kill" | "Coins", position, amount)
}

-- Must differ from this ModuleScript's name ("Remotes"), or the client's WaitForChild
-- finds the module instead of the folder and never sees any event.
local FOLDER_NAME = "RemoteEvents"
local container

if RunService:IsServer() then
	container = Instance.new("Folder")
	container.Name = FOLDER_NAME
	for _, name in EVENT_NAMES do
		local event = Instance.new("RemoteEvent")
		event.Name = name
		event.Parent = container
	end
	container.Parent = script.Parent
else
	container = script.Parent:WaitForChild(FOLDER_NAME)
end

local Remotes = {}
for _, name in EVENT_NAMES do
	Remotes[name] = container:WaitForChild(name)
end

return Remotes
-- Small builders shared by the HUD and shop so every panel has the same look.
local Theme = require(game.ReplicatedStorage.Shared.Config).Ui

local UiKit = {}

function UiKit.corner(parent: Instance, radius: number?)
	local c = Instance.new("UICorner")
	c.CornerRadius = UDim.new(0, radius or Theme.Corner)
	c.Parent = parent
end

function UiKit.stroke(parent: Instance, color: Color3, thickness: number?, transparency: number?)
	local s = Instance.new("UIStroke")
	s.Color = color
	s.Thickness = thickness or 1.5
	s.Transparency = transparency or 0
	s.ApplyStrokeMode = Enum.ApplyStrokeMode.Border
	s.Parent = parent
	return s
end

function UiKit.panel(parent: Instance): Frame
	local f = Instance.new("Frame")
	f.BackgroundColor3 = Theme.Panel
	f.BackgroundTransparency = 0.08
	f.BorderSizePixel = 0
	f.Parent = parent
	UiKit.corner(f)
	UiKit.stroke(f, Theme.Accent, 1.5, 0.55)
	return f
end

function UiKit.label(parent: Instance, text: string, size: number, color: Color3?, bold: boolean?): TextLabel
	local l = Instance.new("TextLabel")
	l.BackgroundTransparency = 1
	l.Text = text
	l.TextSize = size
	l.TextColor3 = color or Theme.Text
	l.Font = if bold then Enum.Font.GothamBold else Enum.Font.Gotham
	l.Parent = parent
	return l
end

return UiKit
